description:
Delay loading replaces each import with a thunk that resolves the real function the first time it is called. Build the same mechanism with ordinary C++:

```cpp
using Fn = int (*)(int);
using Resolver = std::function<Fn(const std::string& name)>;    // like LoadLibrary + GetProcAddress; nullptr if missing

class DelaySlot
{
public:
    DelaySlot(std::string name, Resolver resolver, Fn fallback = nullptr);
    int call(int argument);       // resolves on first use, then calls
    int resolveCount() const;     // how many times the resolver has been asked
    bool resolved() const;        // has a real function (not the fallback) been found?
};
```

- The first `call` asks the resolver for the function. If it returns a function, the slot remembers it, and **every later call goes straight to it** without asking again.
- If the resolver returns `nullptr` and there is a `fallback`, call the fallback this time. The slot does **not** remember failure: the next call asks the resolver again (the DLL might have been installed since).
- If the resolver returns `nullptr` and there is no fallback, throw `std::runtime_error` with the message `"cannot resolve <name>"`.

starter.solution.cpp:
#include <functional>
#include <stdexcept>
#include <string>

using Fn = int (*)(int);
using Resolver = std::function<Fn(const std::string& name)>;

class DelaySlot
{
public:
    DelaySlot(std::string name, Resolver resolver, Fn fallback = nullptr) {}
    int call(int argument) { return 0; }
    int resolveCount() const { return 0; }
    bool resolved() const { return false; }
};

solution.solution.cpp:
#include <functional>
#include <stdexcept>
#include <string>
#include <utility>

using Fn = int (*)(int);
using Resolver = std::function<Fn(const std::string& name)>;

class DelaySlot
{
public:
    DelaySlot(std::string name, Resolver resolver, Fn fallback = nullptr)
        : m_name{ std::move(name) }, m_resolver{ std::move(resolver) }, m_fallback{ fallback } {}

    int call(int argument)
    {
        if (!m_target)
        {
            ++m_asked;
            m_target = m_resolver ? m_resolver(m_name) : nullptr;
            if (!m_target)
            {
                if (m_fallback) return m_fallback(argument);
                throw std::runtime_error("cannot resolve " + m_name);
            }
        }
        return m_target(argument);
    }

    int resolveCount() const { return m_asked; }
    bool resolved() const { return m_target != nullptr; }

private:
    std::string m_name;
    Resolver m_resolver;
    Fn m_fallback;
    Fn m_target{ nullptr };
    int m_asked{ 0 };
};

unitTests:
int twice(int x) { return 2 * x; }
int fallbackZero(int) { return 0; }
TEST("resolves once") { int asked = 0; DelaySlot s{ "twice", [&](const std::string& n) -> Fn { ++asked; return n == "twice" ? twice : nullptr; } }; CHECK(!s.resolved()); CHECK_EQ(s.call(4), 8); CHECK_EQ(s.call(5), 10); CHECK_EQ(s.call(6), 12); CHECK_EQ(s.resolveCount(), 1); CHECK_EQ(asked, 1); CHECK(s.resolved()); }
TEST("missing with a fallback keeps trying") { bool installed = false; DelaySlot s{ "twice", [&](const std::string&) -> Fn { return installed ? twice : nullptr; }, fallbackZero }; CHECK_EQ(s.call(4), 0); CHECK_EQ(s.call(4), 0); CHECK_EQ(s.resolveCount(), 2); installed = true; CHECK_EQ(s.call(4), 8); CHECK_EQ(s.call(4), 8); CHECK_EQ(s.resolveCount(), 3); }
TEST("missing without a fallback throws") {
    DelaySlot s{ "stackWeight", [](const std::string&) -> Fn { return nullptr; } };
    std::string message;
    try { s.call(1); } catch (const std::runtime_error& e) { message = e.what(); }
    CHECK_EQ(message, std::string("cannot resolve stackWeight"));
}
TEST("not called, not resolved") { int asked = 0; DelaySlot s{ "twice", [&](const std::string&) -> Fn { ++asked; return twice; } }; CHECK_EQ(asked, 0); CHECK_EQ(s.resolveCount(), 0); }

